bundle = {
    "resourceType": "Bundle",
    "type": "transaction",
    "entry": [
        {
            "request": {"method": "POST", "url": "patient"},
            "resource": {
                "resourceType": "Patient",
                "identifier": [{"use": "usual", "value": "IPP001"}],
